using NUnit.Framework;

[TestFixture]
public class SwapNumbersTests
{
    [Test]
    public void Swap_ReturnsSwappedPair()
    {
        var result = Swap(10, 20);
        Assert.That(result.a, Is.EqualTo(20));
        Assert.That(result.b, Is.EqualTo(10));
    }

    private (int a, int b) Swap(int a, int b)
    {
        int temp = a;
        a = b;
        b = temp;
        return (a, b);
    }
}
